        IEnumerator Capture(string path){
            string directory=System.IO.Path.GetDirectoryName(path);System.IO.Directory.CreateDirectory(directory);
            Action[] pages={Home,Collection,()=>Detail("cutter"),Season,Shop,Social,Settings,Tutorial,History,StartPractice};string[] names={"harbor","fleet","card","season","shop","social","settings","tutorial","history","battle"};
            for(int i=0;i<pages.Length;i++){pages[i]();if(i==9){for(int n=0;n<600;n++){if(n%45==0){simulation.Bot(0,++sequence);simulation.Bot(1,sequence);}simulation.Step();}snap=simulation.Snapshot(0,"practice","Harbor AI");ApplySnapshot();}yield return new WaitForSeconds(1);CaptureFrame(System.IO.Path.Combine(directory,names[i]+".png"));yield return new WaitForSeconds(.5f);}
            Debug.Log("SCREEN AUDIT COMPLETE");Application.Quit();}
        void CaptureFrame(string path){
            var target=new RenderTexture(540,960,24);target.Create();var previousTarget=arena.Camera.targetTexture;arena.Camera.targetTexture=target;
            var scaler=canvas.GetComponent<CanvasScaler>();scaler.enabled=false;float oldScale=canvas.scaleFactor;canvas.scaleFactor=.6f;
            canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=arena.Camera;canvas.planeDistance=2;Canvas.ForceUpdateCanvases();
            var request=new UnityEngine.Rendering.Universal.UniversalRenderPipeline.SingleCameraRequest{destination=target};UnityEngine.Rendering.RenderPipeline.SubmitRenderRequest(arena.Camera,request);
            var old=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(540,960,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,540,960),0,0);image.Apply();System.IO.File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=old;Destroy(image);arena.Camera.targetTexture=previousTarget;target.Release();Destroy(target);canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.scaleFactor=oldScale;scaler.enabled=true;
        }
