        void BeginBattle(){Clear("battle",true);arena.Reset();snap=null;displayedHand=null;Box(page,15,25,870,155,new Color(ink.r,ink.g,ink.b,.93f));clock=Label(page,"3:00",335,35,230,65,45,gold,TextAnchor.MiddleCenter);score=Label(page,practice?"TRAINING":"LIVE DUEL",45,107,610,60,26);Button(page,"Menu",685,105,170,58,BattleMenu);Box(page,0,1240,900,360,ink);supply=Label(page,"SUPPLY",35,1250,760,40,25,gold);Box(page,35,1300,830,14,panel);supplyFill=Box(page,35,1300,415,14,new Color(.2f,.83f,.78f));handRoot=Rect("Hand",page,25,1330,850,215).gameObject;notice=Label(page,"Select a card, then tap your half of the sea.",40,1170,820,60,23,gold,TextAnchor.MiddleCenter);lastSnapshotAt=Time.unscaledTime;}
        void BattleMenu(){if(screen!="battle")return;var overlay=Box(page,70,470,760,700,ink);Label(overlay.transform,practice?"Training duel":"Duel in progress",35,20,690,80,38,gold);Label(overlay.transform,"The battle continues while this menu is open.",35,115,690,100,26);Button(overlay.transform,"Resume",35,250,690,85,()=>Destroy(overlay.gameObject),true);if(!practice&&!fusionMatch)Button(overlay.transform,"Reconnect",35,360,690,85,()=>{service.OpenMatch(matchId);Destroy(overlay.gameObject);});Button(overlay.transform,"Surrender",35,485,690,85,()=>{Destroy(overlay.gameObject);if(practice)simulation.Surrender(0);else if(fusionMatch)fusionSession.Surrender();else StartCoroutine(service.Request<ErrorResponse>("POST","/v1/matches/"+matchId+"/surrender",null,_=>{}));});Button(overlay.transform,"Return to harbor",35,585,690,65,()=>{service.CloseMatch();LeaveFusion();Home();});}
        void ApplySnapshot(){if(snap==null)return;sequence=Math.Max(sequence,snap.acknowledged);arena.Apply(snap,service.Profile.equipped);float remaining=snap.time<180?180-snap.time:300-snap.time;clock.text=(snap.time>=180?"OT ":"")+Mathf.CeilToInt(remaining/60- .0001f).ToString();int secs=Mathf.Max(0,Mathf.CeilToInt(remaining));clock.text=(snap.time>=180?"OT ":"")+(secs/60)+":"+(secs%60).ToString("00");score.text=(practice?"TRAINING  •  ":"")+snap.score[snap.team]+"  –  "+snap.score[1-snap.team]+"  •  "+snap.opponent;supply.text="SUPPLY  "+snap.supply.ToString("0.0")+" / 10   •   "+(snap.time>=240?"3×":snap.time>=120?"2×":"1×")+"   •   NEXT: "+service.Catalog.Get(snap.next).name;supplyFill.rectTransform.sizeDelta=new Vector2(830*snap.supply/10,14);
            if(displayedHand==null||!displayedHand.SequenceEqual(snap.hand)){CancelDrag();selected=-1;selectedCard=null;displayedHand=(string[])snap.hand.Clone();foreach(Transform c in handRoot.transform)Destroy(c.gameObject);for(int i=0;i<4;i++){int slot=i;var card=service.Catalog.Get(snap.hand[i]);var tile=CardTile(handRoot.transform,card,i*214,0,204,210,()=>SelectCard(slot,card));var drag=tile.gameObject.AddComponent<CardDrag>();drag.select=()=>SelectCard(slot,card);drag.preview=PreviewDrop;drag.cancel=CancelDrag;drag.deploy=point=>{CancelDrag();DeployAt(point);};}}
            if(snap.winner!=-2)Result();
        }
        void Update(){if(screen!="battle")return;if(practice){accumulator+=Mathf.Min(Time.deltaTime,.2f);while(accumulator>=MatchSimulation.StepSeconds){simulation.Step();accumulator-=MatchSimulation.StepSeconds;if(simulation.Time>=botAt){simulation.Bot(1,simulation.Tick);botAt=simulation.Time+1.4f;}}snap=simulation.Snapshot(0,"practice","Harbor AI");ApplySnapshot();}else if(!fusionMatch){while(service.Messages.TryDequeue(out var message)){if(message.kind=="snapshot"){snap=message.snapshot;lastSnapshotAt=Time.unscaledTime;ApplySnapshot();if(FusionBattleSession.Flag("-ranked-autotest"))AuditFusion(snap);}else if(message.reply!=null&&!message.reply.accepted)Toast(message.reply.error);}if(Time.unscaledTime-lastSnapshotAt>4)Toast("Connection interrupted. Open Menu to reconnect.");}
            if(fusionMatch&&Time.unscaledTime-lastSnapshotAt>4)Toast("Connection interrupted. Return to harbor if the duel does not resume.");if(screen!="battle"||snap==null)return;
            if(dragging)PreviewDrop(dragPoint);if(Input.GetKeyDown(KeyCode.Escape)){CancelDrag();selected=-1;}
            if(!dragging&&Input.GetMouseButtonDown(0)&&selected>=0&&!EventSystem.current.IsPointerOverGameObject()&&(Input.touchCount==0||!EventSystem.current.IsPointerOverGameObject(Input.GetTouch(0).fingerId))){DeployAt(Input.mousePosition);}
        }
        void SelectCard(int slot,CardDef card){selected=slot;selectedCard=card.id;foreach(Transform child in handRoot.transform){var image=child.GetComponent<Image>();if(image)image.color=child.GetSiblingIndex()==slot?new Color(.35f,.42f,.22f):panel;}Toast(card.name+" • Tap or drag into clear water ("+card.cost+")");}
        void CancelDrag(){dragging=false;if(placement)placement.Hide();}
        bool DropPoint(Vector2 point,out Vector3 pos){pos=Vector3.zero;if(!arena.Camera)return false;var plane=new Plane(Vector3.up,Vector3.zero);var ray=arena.Camera.ScreenPointToRay(point);if(!plane.Raycast(ray,out float distance))return false;pos=ray.GetPoint(distance);
            RectTransformUtility.ScreenPointToLocalPointInRectangle(page,point,null,out var local);float y=page.rect.yMax-local.y;
            return RectTransformUtility.RectangleContainsScreenPoint(page,point,null)&&y>180&&y<1170;
        }
        void PreviewDrop(Vector2 point){if(screen!="battle"||selected<0||snap==null)return;dragging=true;dragPoint=point;if(!placement){var go=new GameObject("Deployment overlay");go.transform.SetParent(arena.Root.transform);placement=go.AddComponent<PlacementOverlay>();}bool inside=DropPoint(point,out var pos);var card=service.Catalog.Get(selectedCard);bool valid=placement.Show(snap,card,pos,inside);Toast(!PlacementOverlay.Affordable(snap,card)?"Not enough supply or fleet capacity":valid?"Release to deploy • Green water is available":"Cannot deploy here • Move into green water");}
        void DeployAt(Vector2 point){if(screen!="battle"||selected<0||snap==null)return;if(!DropPoint(point,out var pos)){Toast("Deployment cancelled • Drop in the arena.");return;}var card=service.Catalog.Get(selectedCard);if(!PlacementOverlay.Affordable(snap,card)){Toast("Not enough supply or fleet capacity.");return;}if(!MatchSimulation.LegalPlacement(snap.team,card,pos.x,pos.z,snap.units)){Toast("Choose green water in your deployment area.");return;}var cmd=new DeployRequest{sequence=++sequence,slot=selected,x=pos.x,z=pos.z,expectedCard=selectedCard};if(practice){var reply=simulation.Deploy(0,cmd);Toast(reply.accepted?"Fleet deployed.":reply.error);}else if(fusionMatch){arena.DeploymentFeedback(pos.x,pos.z);fusionSession.Deploy(cmd);Toast("Deploying…");}else service.Deploy(cmd);selected=-1;selectedCard=null;foreach(Transform child in handRoot.transform){var image=child.GetComponent<Image>();if(image)image.color=panel;}}
        void Result(){service.CloseMatch();Clear("result");bool win=snap.winner==snap.team;Header(snap.winner==-1?"Honors shared.":win?"The sea is yours.":"A fleet worth rebuilding.",practice?"Training complete • No rewards or trophies":fusionMatch&&!rankedMatch?"Private duel complete • No rewards or trophies":"The server is recording your result.");Label(page,snap.score[snap.team]+"  :  "+snap.score[1-snap.team],45,410,810,180,110,gold,TextAnchor.MiddleCenter);Label(page,"vs "+snap.opponent,45,620,810,70,36,cream,TextAnchor.MiddleCenter);Button(page,"Return to harbor",45,1040,810,105,()=>{LeaveFusion();Home();},true);Button(page,practice?"Train again":"Find another captain",45,1170,810,85,()=>{if(practice)StartPractice();else if(fusionMatch){LeaveFusion();if(rankedMatch)RankedBattle();else FusionLobby();}else Queue("");});if(!practice&&rankedMatch&&fusionMatch)StartCoroutine(RefreshRankedResult());else if(!practice&&!fusionMatch)StartCoroutine(RefreshResult());}
        IEnumerator RefreshResult(){yield return new WaitForSeconds(.5f);yield return service.Request<Profile>("GET","/v1/profile",null,p=>service.Profile=p);if(screen=="fleet")RenderCollection();else if(screen=="home")Home();if(screen=="result")Toast(service.Error??"Progress saved • "+service.Profile.gold+" gold • "+service.Profile.trophies+" trophies");}
        void OnApplicationFocus(bool focused){if(!focused)CancelDrag();}
        void OnApplicationPause(bool paused){if(paused)CancelDrag();if(!paused&&screen=="battle"&&!practice&&!fusionMatch)service.OpenMatch(matchId);if(FusionBattleSession.Flag("-ranked-autotest"))StartCoroutine(FusionTestTimeout());}
    }
}







